// Confere o envio do painel antes de tocar no YouTube. Nada aqui chama a API.
const MINIMO_MINUTOS = 20; // o painel agenda +30 min; abaixo de 20 recusa (folga para o tempo do upload)
const item = $input.first();
const b = item.json.body || {};
const erros = [];

// arquivo: campo "video" (ou o primeiro anexo video/*)
const bin = item.binary || {};
const campoVideo = bin.video ? 'video' : Object.keys(bin).find(k => String(bin[k].mimeType || '').startsWith('video/'));
const arquivo = campoVideo ? bin[campoVideo] : null;
if (!arquivo) erros.push('faltou o arquivo de vídeo (campo "video")');
else if (!String(arquivo.mimeType || '').startsWith('video/')) erros.push(`o anexo não é vídeo (${arquivo.mimeType})`);

const titulo = String(b.titulo ?? '').replace(/[<>]/g, '').trim();
if (!titulo) erros.push('faltou o título');
if (titulo.length > 100) erros.push(`título com ${titulo.length} caracteres (máximo 100)`);

const descricao = String(b.descricao ?? '').replace(/[<>]/g, '').trim();
if (descricao.length > 5000) erros.push(`descrição com ${descricao.length} caracteres (máximo 5000)`);

const tags = String(b.tags ?? '').split(',').map(t => t.trim().replace(/^#/, '')).filter(Boolean);
if (tags.join(',').length > 500) erros.push('tags passam de 500 caracteres');

// horário: aceita publicar_em_utc ou publicar_em, sempre com fuso
const bruto = String(b.publicar_em_utc || b.publicar_em || '').trim();
const quando = new Date(bruto);
let publishAt = null;
if (!bruto || isNaN(quando.getTime())) erros.push('publicar_em ausente ou inválido (ISO 8601, ex.: 2026-11-19T19:30:00-03:00)');
else if (!/(Z|[+-]\d{2}:?\d{2})$/i.test(bruto)) erros.push('publicar_em precisa trazer o fuso (-03:00 ou Z)');
else {
  const minutos = (quando.getTime() - Date.now()) / 60000;
  if (minutos < MINIMO_MINUTOS) erros.push(`publicar_em está a ${Math.round(minutos)} min; o mínimo é ${MINIMO_MINUTOS}`);
  publishAt = quando.toISOString().replace(/\.\d{3}Z$/, 'Z');
}

// duplicado: mesma "chave" já agendada por este fluxo
const chave = String(b.chave ?? '').trim();
const memoria = $getWorkflowStaticData('global');
const anterior = chave && memoria.chaves ? memoria.chaves[chave] : null;
const duplicado = Boolean(anterior && anterior.status !== 'falhou'); // falhou = nada foi agendado, pode reenviar
if (duplicado) erros.push(`este envio (${chave}) já foi recebido antes (${anterior.status || 'agendado'}; vídeo ${anterior.video_id || '?'})`);

return [{
  json: {
    valido: erros.length === 0,
    status: duplicado ? 409 : 400,
    erros,
    titulo, descricao, tags: tags.join(','),
    publish_at: publishAt,
    publicar_em: String(b.publicar_em || bruto),
    episodio: String(b.episodio ?? ''),
    chave,
  },
  binary: arquivo ? { video: arquivo } : {},
}];

// Só segue se a credencial OAuth estiver ligada ao canal do projeto.
const CANAL_ESPERADO = 'UCKSkHV2WKpfezCBBi6BeFUQ'; // ID do canal do projeto, começa com UC (24 caracteres)

const canais = $input.all().map(i => i.json).filter(c => c && c.id);
const ids = canais.map(c => c.id);
let erro = null;
if (!/^UC[\w-]{22}$/.test(CANAL_ESPERADO)) {
  erro = 'o ID do canal do projeto ainda não foi preenchido no nó "Conferir canal"';
} else if (!ids.includes(CANAL_ESPERADO)) {
  const achados = canais.map(c => `${(c.snippet && c.snippet.title) || '?'} (${c.id})`).join(', ') || 'nenhum canal';
  erro = `a credencial do YouTube está ligada a ${achados}, não ao canal do projeto (${CANAL_ESPERADO})`;
}
if (erro) return [{ json: { canal_ok: false, erro } }];

const v = $('Validar dados').first();
const canal = canais.find(c => c.id === CANAL_ESPERADO);
return [{
  json: { ...v.json, canal_ok: true, canal_id: canal.id, canal_nome: (canal.snippet && canal.snippet.title) || '' },
  binary: v.binary,
}];

// Guarda o resultado pela chave do envio: o painel consulta pelo webhook de status
// (e um reenvio com a mesma chave é recusado como duplicado).
const r = $input.first().json;
const v = $('Conferir canal').first().json;
const videoId = r.id || r.videoId || null;
const memoria = $getWorkflowStaticData('global');
memoria.chaves = memoria.chaves || {};
if (v.chave) {
  memoria.chaves[v.chave] = videoId
    ? { status: 'agendado', video_id: videoId, url: `https://youtube.com/shorts/${videoId}`,
        publicar_em: v.publicar_em, episodio: v.episodio, em: new Date().toISOString() }
    : { status: 'conferir', video_id: null, episodio: v.episodio, em: new Date().toISOString(),
        erro: 'o YouTube aceitou o envio mas não devolveu o ID do vídeo; confira no YouTube Studio' };
  const todas = Object.entries(memoria.chaves).sort((a, b) => String(a[1].em).localeCompare(String(b[1].em)));
  for (const [k] of todas.slice(0, Math.max(0, todas.length - 300))) delete memoria.chaves[k];
}
return [{ json: { chave: v.chave, ...(memoria.chaves[v.chave] || {}) } }];

// Pega de novo os dados + o arquivo conferidos (não depende do nó de resposta repassar o binário).
const v = $('Conferir canal').first();
return [{ json: v.json, binary: v.binary }];

// O upload deu erro: guarda para o painel ver no webhook de status. 'falhou' libera reenviar a mesma chave.
const e = $input.first().json;
const v = $('Conferir canal').first().json;
const memoria = $getWorkflowStaticData('global');
memoria.chaves = memoria.chaves || {};
const erro = (e.error && (e.error.message || e.error.description)) || e.error || e.message || 'erro desconhecido';
if (v.chave) memoria.chaves[v.chave] = { status: 'falhou', video_id: null, episodio: v.episodio,
  em: new Date().toISOString(), erro: 'falha no envio ao YouTube: ' + String(erro) };
return [{ json: { chave: v.chave, ...(memoria.chaves[v.chave] || {}) } }];

// Resultado de um envio pela chave. 'desconhecido' = ainda subindo (o n8n só grava ao fim da execução)
// ou a chave nunca chegou.
const chave = String(($json.query || {}).chave || '').trim();
const memoria = $getWorkflowStaticData('global');
const r = chave && memoria.chaves ? memoria.chaves[chave] : null;
return [{ json: r ? { ok: true, chave, ...r, status: r.status || 'agendado' } : { ok: true, chave, status: 'desconhecido' } }];
